import{_ as l,l as i,o as e,c as s,v as r,p as n,x as t,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"买卖价差的分解","description":"","frontmatter":{"title":"买卖价差的分解","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/spread-decomposition.md","filePath":"quant/spread-decomposition.md","lastUpdated":1789023840000}'),E={name:"quant/spread-decomposition.md"};function m(c,a,B,u,A,_){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="买卖价差的分解" tabindex="-1">买卖价差的分解 <a class="header-anchor" href="#买卖价差的分解" aria-label="Permalink to &quot;买卖价差的分解&quot;">​</a></h1><div class="epigraph"><p>买卖价差不是单一成本的标签。它同时补偿处理指令的经营费用、持有不愿持有的存货的风险，以及与可能知情的对手成交的预期损失。</p><footer>—— 据 O&#39;Hara, Market Microstructure Theory 与 Harris, Trading and Exchanges 对价差构成的论述整理</footer></div><p><a href="/quant/order-imbalance">上一课</a>把两侧深度收成了标量。报价价差 \\(s=a-b\\) 在 <a href="/quant/lob-structure">LOB</a> 里已经定义过，本课不重画 BBO。缺口是：同样宽的价差，可能来自处理成本、存货风险，或知情对手的预期损失。O&#39;Hara 把价格形成分成存货与信息两条主线。下一课序先进入<a href="/quant/continuous-vs-auction">市场设计</a>：匹配协议一变，这套会计的对象就不是同一张连续簿。Roll、Glosten-Milgrom、Kyle 要等到价格形成课序，本课只把连续限价簿上的三项拆开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若价差只是「交易所收的一点费用」，更激烈的竞争应把它压到接近处理成本。事实是：即使电子化把处理成本压得很低，价差仍随公告、随个股信息不对称、随存货是否集中而变。需要解释的不是价差是否存在——簿上你已经见过它——而是它为什么随对象与随时间改变，以及改变的是哪一部分。</p><p>三个候选部分对应三种不同的状态变量。处理（order processing）与成交笔数、系统费用、固定经营成本有关，近似每笔一块，对方向不敏感。存货（inventory）与做市商已经持有的头寸、风险厌恶、对冲成本有关，价差与报价中点会随存货偏移。逆向选择（adverse selection）与对手知情的概率、价值的不确定性有关，成交之后有效价值朝成交方向跳，流动性提供者的事后收入小于事前报价价差。O&#39;Hara 的书表明，只看其中一条线会把另两条的现象误读成自己的证据。分解问题因此是识别问题：从可观测的报价、成交与后续价格里，如何把这三块分开，而不是另写一个「总摩擦」。</p><h3 id="报价价差、有效价差与事后收入" tabindex="-1">报价价差、有效价差与事后收入 <a class="header-anchor" href="#报价价差、有效价差与事后收入" aria-label="Permalink to &quot;报价价差、有效价差与事后收入&quot;">​</a></h3><p>报价价差是 BBO 之差，可能没有人在上面成交。有效价差用成交价相对当时中间价的偏离，\\(s_{\\mathrm{e}}=2q(p-m)\\)，其中 \\(q\\) 为成交方向。它度量实际付出的即时成本。成交之后一段时间（若干笔或若干时钟）中间价变为 \\(m&#39;\\)，实现价差 \\(s_{\\mathrm{r}}=2q(p-m&#39;)\\) 近似流动性提供者的事后收入：若价格已向成交方向跳走，收入被吃掉。有效价差减实现价差，常被当作逆向选择的经验代理——价格向对手有利方向永久移动的那一部分。这套会计不依赖某一个结构模型，但解释必须回到存货与信息：存货调整也会让报价中点移动，不一定是价值发现。</p><p><span class="marginnote">把报价价差除以二当成「半价差成本」只对立刻吃 BBO 的市价单成立。限价单成交在己方报价上，即时有效价差可能为零甚至为负（价格改善），成本改写在等待与被选中的概率上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>概念分解写为</p> \\[s = s_{\\mathrm{proc}} + s_{\\mathrm{inv}} + s_{\\mathrm{as}}, \\]<p>三项都是不可直接观测的。经验上用价格在成交后的行为去拆。若中间价是鞅、买卖随机，成交价在买卖之间回跳，Roll 用负的一阶协方差恢复有效价差，那里面混合了处理与部分存货，原则上不含永久信息——因为信息会破坏「中间价鞅加独立方向」的假设。若成交后中间价出现与方向同号的漂移，则把漂移归因于信息，把回跳归因于暂时成分。Harris 对交易成本的讨论允许这种暂时/永久的切分作为组织数据的方法，而不是作为唯一真实。</p><p>存货部分的识别需要头寸或可代理头寸的状态。报价中点随累积净卖出上移、随净买入下移，是存货模型的特征：做市商用中点去诱导能减少存货的成交。信息部分的特征是：成交方向预测后续价值，买卖报价不对称地更新，价差在信息密集时变宽。纯处理成本的特征是：价差与近期方向无关，成交后价格回跳到原中点附近。实际市场三者同时在，方法只能强调哪一种矩被哪一项主导，不能声称点识别了三个非负加总项。</p><h3 id="暂时成分与永久成分" tabindex="-1">暂时成分与永久成分 <a class="header-anchor" href="#暂时成分与永久成分" aria-label="Permalink to &quot;暂时成分与永久成分&quot;">​</a></h3><p>把一次主动买的冲击拆成：立刻把成交价放到卖价，随后一部分回落（暂时），一部分留在新的中间价里（永久）。暂时成分对应处理加存货的均值回复；永久成分对应信息被写进价格。窗口太短，永久看起来像暂时；窗口太长，无关的公开信息会混进永久。事件时间上「随后 \\(k\\) 笔」通常比「随后五分钟」更贴近机制，但 \\(k\\) 的选择仍是设定。分解表应报告多个窗口，而不是只给一个讨喜的比例。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>处理成本要求价差至少覆盖每笔的经营费用。没有这一项，即使没有风险与信息，指令匹配也不能免费；有了电子撮合，这一项可以很小，却仍为正。存货机制是风险分担：流动性提供者成为对方的对手方，暂时持有不想要的风险，必须用价差与中点偏移来控制头寸分布。头寸回到目标附近后，这一项对价差的压力下降。信息机制是逆向选择：对手在知情时才成交，不知情时才离开；提供流动性的条件期望损失必须用更宽的价差弥补。Glosten-Milgrom 把这一项写成买卖报价等于条件期望价值，价差是两个条件期望之差；Kyle 把同类问题写成随订单流线性变化的价格，而不是固定的双向报价。</p><p>三项对数据的指纹不同。处理成本几乎不随公告跳变。存货使报价中点与累积成交负相关，并产生均值回复。信息使成交方向预测未来中点，并在信息到达前后抬高价差。O&#39;Hara 强调信息模型与存货模型不是修辞差异：前者改变的是信念，后者改变的是风险承担。把所有中点移动都叫「发现价值」，会把存货诱导的报价调整算进 \\(\\alpha\\)。把所有回跳都叫「无信息」，又会忽略知情交易同样可以伴随短暂的过度反应与补单。</p><h3 id="竞争如何压哪一项" tabindex="-1">竞争如何压哪一项 <a class="header-anchor" href="#竞争如何压哪一项" aria-label="Permalink to &quot;竞争如何压哪一项&quot;">​</a></h3><p>竞争加剧时，处理成本项最先被压，因为它最像可复制的经营利润。存货项取决于还有多少人愿意在同一时刻承担方向风险，以及他们能否对冲；对冲市场若同时变薄，存货项不必下降。逆向选择项由信息不对称决定，竞争本身消灭不了知情者；更多的非知情流动性反而可能摊薄单位逆向选择，使价差中的信息份额下降。因此「价差变窄」没有唯一叙事：要看变窄的是回跳还是永久冲击。Harris 对竞争与市场结构的讨论，应读成改变了三项的相对权重，而不是只改变了一个 \\(s\\)。</p><p><span class="marginnote">费用与回扣会改写会计。收取 taker 费、补贴 maker 时，名义报价价差可以很窄甚至为零，经济价差要把费用加回去。分解若只看 BBO 之差，会把费用结构误当成微观结构成本下降。</span></p>',22)),(e(),n(h,null,{default:t(()=>[d(o,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TB%0A%20%20S%5B%22%E8%A7%82%E5%AF%9F%E5%88%B0%E7%9A%84%E4%BB%B7%E5%B7%AE%22%5D%20--%3E%20P%5B%22%E5%A4%84%E7%90%86%E6%88%90%E6%9C%AC%22%5D%0A%20%20S%20--%3E%20V%5B%22%E5%AD%98%E8%B4%A7%E8%A1%A5%E5%81%BF%22%5D%0A%20%20S%20--%3E%20A%5B%22%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%22%5D%0A%20%20P%20--%3E%20T%5B%22%E6%9A%82%E6%97%B6%EF%BC%9A%E6%88%90%E4%BA%A4%E5%90%8E%E5%9B%9E%E8%B7%B3%22%5D%0A%20%20V%20--%3E%20T%0A%20%20V%20--%3E%20M%5B%22%E4%B8%AD%E7%82%B9%E9%9A%8F%E5%A4%B4%E5%AF%B8%E5%81%8F%E7%A7%BB%22%5D%0A%20%20A%20--%3E%20F%5B%22%E6%B0%B8%E4%B9%85%EF%BC%9A%E6%96%B9%E5%90%91%E9%A2%84%E6%B5%8B%E5%90%8E%E7%BB%AD%E4%BB%B7%E5%80%BC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>三加总不是唯一合法的切法。有人把存货并入暂时成分，只谈暂时与永久；有人把处理与存货合并为「非信息」。只要在文中定义清楚，不与 O&#39;Hara 的两条理论主线打架即可。不能识别的是：没有头寸数据时存货与信息都让中点移动；没有事后窗口时只有一个 \\(s\\)。Roll 在中间价鞅的假设下把有效价差从回跳里读出，一旦信息主导、协方差变正，该项分解失败，应改读信息模型，而不是强行开平方。</p><p>限价单市场里「做市商」是一群不断更换的挂单者，存货是分散的，分解仍有意义，但「单一专家的头寸」不再存在。暗池与中点成交把一部分量移出报价价差的会计。不同时段（开盘拍卖、连续、收盘）三项权重不同，全日平均会抹平。跨资产比较必须用相对价差（除以价格），但相对价差又与价格水平、tick 制度纠缠。分解是解释工具，不是可以在每只股票每个五分钟上无误差输出三色饼图的机器。</p><p><span class="marginnote">本篇不引用未列入的计量分解论文。Roll（1984）、Glosten-Milgrom（1985）、Kyle（1985）给出的是机制极端情形；Harris 与 O&#39;Hara 给出把它们放在同一价差里阅读的语言。具体百分比来自你的样本与窗口。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>价差概念上可分成处理、存货与逆向选择；经验上常用暂时回跳与永久方向漂移去代理后两项。</li><li>报价价差、有效价差、实现价差分别对应展示成本、即时成交成本与流动性提供者的事后收入。</li><li>处理几乎与方向无关；存货移动中点并制造回复；信息让方向预测后续价值并加宽价差。</li><li>竞争主要压可复制的处理利润；信息不对称不因竞争而自动消失。</li><li>Roll 读回跳，Glosten-Milgrom 读条件期望之差，Kyle 读订单流冲击；三者不是同一会计恒等式。</li><li>费用、隐藏流动性、时段与识别不足，限制把三项写成精确的非负分解。</li><li>出处：O&#39;Hara, <em>Market Microstructure Theory</em>；Harris, <em>Trading and Exchanges</em>。模型情形见 Roll (1984)、Glosten-Milgrom (1985)、Kyle (1985)。</li></ul>',6))])}const b=l(E,[["render",m]]);export{f as __pageData,b as default};
